const fs = require('fs');
const path = require('path');

const VERSION = 'v0.4.7-r2';

const files = {"frontend/src/App.tsx":"","frontend/src/PurchasesBlock.tsx":"","frontend/src/RecentActivityPanel.tsx":"","frontend/src/api.ts":"","frontend/src/types.ts":"","frontend/src/styles.css":"","backend/prisma/schema.prisma":"","backend/src/deals/deals.controller.ts":"","backend/src/deals/deals.service.ts":"","backend/src/purchases/purchases.service.ts":""};

function decode(value) {
  return Buffer.from(value, 'base64').toString('utf8');
}

for (const relativePath of Object.keys(files)) {
  if (!fs.existsSync(relativePath)) {
    console.error('Missing: ' + relativePath);
    process.exit(1);
  }
}

for (const [relativePath, encoded] of Object.entries(files)) {
  const backup = relativePath + '.bak-v047-r2';

  if (!fs.existsSync(backup)) {
    fs.copyFileSync(relativePath, backup);
  }

  fs.writeFileSync(
    relativePath,
    decode(encoded),
    'utf8'
  );
}

